import pathlib,json,numpy as np,pandas as pd
P=pathlib.Path(__file__).parent;O=P/'review_output';s=pd.read_pickle(O/'cell_structure.pkl');st=pd.read_csv(O/'cluster_structure_review.tsv',sep='\t');dec=json.loads((O/'reviewer_decisions.json').read_text());ev=pd.read_csv(O/'selected_gene_evidence.tsv.gz',sep='\t');ev['quality']=ev.detection_fraction*ev.patient_mean_log2_difference.clip(lower=0);ev=ev.sort_values('quality',ascending=False).drop_duplicates(['cluster_id','gene']).set_index(['cluster_id','gene'])
pairs={'MixPlatelet':[('PF4','C1QA')],'MixTMacro':[('CD3D','C1QA'),('CD3E','CSF1R')],'MixOsteoMacro':[('RUNX2','CD163'),('IFITM5','C1QA')],'MixMyeloidStroma':[('CD163','DCN'),('C1QA','COL3A1')],'MixEndoEpi':[('PECAM1','SFTPB'),('CDH5','SLC34A2')],'MixPlasmaDC':[('IGKC','LILRA4')],'MixBPlasma':[('MS4A1','JCHAIN')],'MixBPlasmaDC':[('MS4A1','LILRA4'),('IGKC','LILRA4')]}
rows=[]
for cl,x in dec.items():
 for a,b in pairs.get(x['label'],[]):
  if (cl,a) in ev.index and (cl,b) in ev.index:
   da=ev.loc[(cl,a),'detection_fraction'];db=ev.loc[(cl,b),'detection_fraction'];rows.append({'cluster_id':cl,'gene_A':a,'gene_B':b,'detection_A':da,'detection_B':db,'minimum_codetection_fraction':max(0,da+db-1),'interpretation':'簇内检出比例的数学下界；不区分双细胞、环境RNA、融合或真实生物程序'})
pd.DataFrame(rows).to_csv(O/'mixed_program_evidence.tsv',sep='\t',index=False)
reg=pd.read_csv(O/'regional_CNV_summary.tsv.gz',sep='\t');z=reg[reg.method.isin(['immune_endothelial_reference','lymphoid_reference']) & reg.direction.isin(['gain','loss'])].copy();z.loc[z.direction=='loss','value']*=-1;z=z.groupby(['sample_id','cluster_id','method','chromosome'],as_index=False).value.sum();z=z.pivot(index=['sample_id','cluster_id','chromosome'],columns='method',values='value').reset_index();both=z.iloc[:,3:].notna().all(axis=1);z['both_reported']=both;z['abs_difference_Mb']=(z.immune_endothelial_reference-z.lymphoid_reference).abs();z['direction_agrees_both_reported']=np.where(both,np.sign(z.immune_endothelial_reference)==np.sign(z.lymphoid_reference),np.nan);z.to_csv(O/'alternative_reference_sensitivity.tsv',sep='\t',index=False)
# Original roster and sample totals checked independently.
r=pd.read_csv(P/'anonymous_cell_cluster_roster.tsv.gz',sep='\t'); print('ROSTER columns',list(r));print('ROSTER',len(r),'unique',r.cell_id.nunique(),'set match',set(r.cell_id)==set(s.cell_id));meta=pd.read_csv(P/'sample_technical_metadata.tsv',sep='\t');print('SAMPLE counts match',s.groupby('sample_id').size().sort_index().equals(meta.set_index('sample_id').cells.sort_index()));
summary=st.groupby('source_id').agg(cells=('cells','sum'),clusters=('cluster_id','size'));cov=pd.read_csv(O/'copykat_sample_cluster_metrics.tsv',sep='\t');summary['copykat_cells']=cov.groupby('source_id').copykat_cells.sum();summary['copykat_coverage']=summary.copykat_cells/summary.cells;summary['unresolved_cells']=st[st.cluster_id.map(lambda c:dec[c]['label']=='U')].groupby('source_id').cells.sum();summary.to_csv(O/'source_coverage_summary.tsv',sep='\t');print(summary.to_string());print('MIX',pd.DataFrame(rows).to_string(index=False));print('ALT',z.groupby('sample_id').agg(chromosome_records=('chromosome','size'),both_reported=('both_reported','sum'),mean_agreement=('direction_agrees_both_reported','mean'),max_difference=('abs_difference_Mb','max')).to_string());
print('Alt disagree clusters',z[z.direction_agrees_both_reported==0].cluster_id.unique())
